import type { DietaryRestriction } from '@/contexts/AuthContext';
import { CATEGORIES } from './meals';
import { renderText } from './portions';
import type { Ingredient, Meal, MealType } from './meals';

/**
 * One row of the Supabase `recipes` table (supabase/recipes.sql).
 * Rows are generated by scripts/recipes/build.mjs, which computes the nutrition
 * from the ingredient amounts, so nothing is derived or guessed here.
 */
export type RawRecipe = {
  id: string;
  name: string;
  description: string;
  meal_type: MealType;
  main: string;
  emoji: string;
  prep_time_min: number;
  difficulty: string;
  calories: number;
  protein_g: number;
  carbs_g: number;
  fat_g: number;
  fiber_g: number;
  sugar_g: number;
  sodium_mg: number;
  ingredients: Ingredient[];
  seasonings: string[];
  instructions: string[];
  appliances: string[];
  keywords: string[];
  dietary_tags: DietaryRestriction[];
  sort: number;
};

function rowToMeal(row: RawRecipe): Meal {
  // Numbers that follow the portion are written as markers; show them for the standard recipe.
  const hasMarkers = [...row.instructions, ...row.seasonings].some(t => t.includes('{'));
  const plain = (texts: string[]) => texts.map(t => renderText(t, 1, row.ingredients));
  return {
    id: `r_${row.id}`,
    name: row.name,
    description: row.description,
    prepTime: row.prep_time_min,
    calories: row.calories,
    proteinG: row.protein_g,
    carbsG: row.carbs_g,
    fatG: row.fat_g,
    fiberG: row.fiber_g,
    sugarG: row.sugar_g,
    sodiumMg: row.sodium_mg,
    difficulty: row.difficulty,
    appliances: row.appliances,
    mealType: row.meal_type,
    dietaryTags: row.dietary_tags,
    tags: row.keywords.filter(k => CATEGORIES.includes(k)),
    keywords: row.keywords,
    emoji: row.emoji,
    main: row.main,
    ingredients: row.ingredients,
    seasonings: hasMarkers ? plain(row.seasonings) : row.seasonings,
    instructions: hasMarkers ? plain(row.instructions) : row.instructions,
    ...(hasMarkers ? { templates: { instructions: row.instructions, seasonings: row.seasonings } } : {}),
  };
}

export function rowsToMeals(rows: RawRecipe[]): Meal[] {
  return [...rows].sort((a, b) => a.sort - b.sort).map(rowToMeal);
}
